`housing_management_number` int(11) DEFAULT 0 comment '宿管编号',
`name_of_accommodation_manager` varchar(64) comment '宿管姓名',
`recommend` int(11) DEFAULT '0' NOT NULL comment '智能推荐',
`create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
`update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
PRIMARY KEY (student_information_id))ENGINE=InnoDB DEFAULT CHARSET=utf8 comment '学生信息';

DROP TABLE IF EXISTS `apply_for_a_change_of_bed`;
CREATE TABLE `apply_for_a_change_of_bed`(apply_for_a_change_of_bed_id int(11) NOT NULL AUTO_INCREMENT COMMENT '申请换寝ID',
`student_no` int(11) DEFAULT 0 comment '学生编号',
`student_name` varchar(64) comment '学生姓名',
`class_name` varchar(64) comment '班级名称',
`name_of_dormitory` varchar(64) comment '寝室名称',
`located_in_the_building` varchar(64) comment '所在楼宇',
`housing_management_number` int(11) DEFAULT 0 comment '宿管编号',
`application_time` date comment '申请时间',
`reason_for_application` varchar(64) comment '申请原因',
`examine_state` varchar(16) DEFAULT '未审核' NOT NULL comment '审核状态',
`examine_reply` varchar(16) DEFAULT '' comment '审核回复',
`recommend` int(11) DEFAULT '0' NOT NULL comment '智能推荐',
`create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
`update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
PRIMARY KEY (apply_for_a_change_of_bed_id))ENGINE=InnoDB DEFAULT CHARSET=utf8 comment '申请换寝';

DROP TABLE IF EXISTS `leave_reporting`;
CREATE TABLE `leave_reporting`(leave_reporting_id int(11) NOT NULL AUTO_INCREMENT COMMENT '请假报备ID',
`student_no` int(11) DEFAULT 0 comment '学生编号',
