`reason_for_taking_leave` varchar(64) comment '请假原因',
`recommend` int(11) DEFAULT '0' NOT NULL comment '智能推荐',
`create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
`update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
PRIMARY KEY (leave_reporting_id))ENGINE=InnoDB DEFAULT CHARSET=utf8 comment '请假报备';

DROP TABLE IF EXISTS `repair_application`;
CREATE TABLE `repair_application`(repair_application_id int(11) NOT NULL AUTO_INCREMENT COMMENT '报修申请ID',
