`lack_of_sleep_time` date comment '缺寝时间',
`reasons_for_lack_of_sleep` varchar(64) comment '缺寝原因',
`recommend` int(11) DEFAULT '0' NOT NULL comment '智能推荐',
`create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
`update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
PRIMARY KEY (lack_of_bed_registration_id))ENGINE=InnoDB DEFAULT CHARSET=utf8 comment '缺寝登记';

DROP TABLE IF EXISTS `migration_records`;
CREATE TABLE `migration_records`(migration_records_id int(11) NOT NULL AUTO_INCREMENT COMMENT '迁出记录ID',
