`update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
PRIMARY KEY (migration_records_id))ENGINE=InnoDB DEFAULT CHARSET=utf8 comment '迁出记录';

DROP TABLE IF EXISTS `repair_record`;
CREATE TABLE `repair_record`(repair_record_id int(11) NOT NULL AUTO_INCREMENT COMMENT '报修记录ID',
`student_no` int(11) DEFAULT 0 comment '学生编号',
`student_name` varchar(64) comment '学生姓名',
