PRIMARY KEY (repair_record_id))ENGINE=InnoDB DEFAULT CHARSET=utf8 comment '报修记录';

DROP TABLE IF EXISTS `announcement_management`;
CREATE TABLE `announcement_management`(announcement_management_id int(11) NOT NULL AUTO_INCREMENT COMMENT '公告管理ID',
`title` varchar(64) comment '标题',
`housing_management_number` int(11) DEFAULT 0 comment '宿管编号',
`name_of_accommodation_manager` varchar(64) comment '宿管姓名',
`release_time` date comment '发布时间',
`content_details` text comment '内容详情',
`recommend` int(11) DEFAULT '0' NOT NULL comment '智能推荐',
`create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
`update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
PRIMARY KEY (announcement_management_id))ENGINE=InnoDB DEFAULT CHARSET=utf8 comment '公告管理';

